
const CCTV_SECRET={"offsets":{"A":160,"B":-80,"C":50},"anchors":{"A":["CAM-0043","CAM-0237"],"B":["CAM-0133","CAM-0075"],"C":["CAM-0198","CAM-0073"]},"route":["CAM-0067","CAM-0003","CAM-0243"],"movementTimes":["01:38:00","01:39:22","01:41:40"],"inputs":["VIS-03","VIS-04","VIS-05","VIS-06"],"outputs":["EVID_CCTV_SYNC","VIS-08","VIS-12"]};
const CCTV_BYID=Object.fromEntries(CCTV_RECORDS.map(x=>[x.id,x]));
const CCTV_INPUT=CCTV_SECRET.inputs,CCTV_OUT=CCTV_SECRET.outputs;
function CCTV_DEFAULT(){return {filters:{camera:'',type:'',date:'',query:''},page:0,selected:'',slot:'A1',offsets:{A:'',B:'',C:''},anchor:{A1:'',A2:'',B1:'',B2:'',C1:'',C2:''},route:['','',''],routeTimes:['','',''],assessment:'',blindspot:'',source:'',notes:'',attempts:0,solved:false};}
function cctvHasInputs(){return CCTV_INPUT.every(x=>STATE.found.has(x));}
function cctvExport(){const st=STATE.cctv;return {filters:st.filters,page:st.page,selected:st.selected,slot:st.slot,offsets:st.offsets,anchor:st.anchor,route:st.route,routeTimes:st.routeTimes,assessment:st.assessment,blindspot:st.blindspot,source:st.source,notes:st.notes,attempts:st.attempts};}
function cctvUtc(t){return Date.parse(t);}
function cctvRawTime(t){return new Date(t).getTime();}
function cctvTimeOnly(t){return new Date(t).toISOString().slice(11,19);}
function cctvCheck(st,found){if(!st||!CCTV_INPUT.every(id=>found.has(id))||!found.has('VIS-10'))return false;
 for(const cam of ['A','B','C']){const offset=Number(st.offsets[cam]);if(String(st.offsets[cam]).trim()===''||!Number.isInteger(offset)||offset!==CCTV_SECRET.offsets[cam])return false;
  for(let k=0;k<2;k++){const id=st.anchor[cam+(k+1)],f=CCTV_BYID[id];if(!f||f.camera!==cam||id!==CCTV_SECRET.anchors[cam][k])return false;
    const corrected=cctvRawTime(f.rawISO)-offset*1000;
    if(corrected!==Date.parse(k===0?'2026-11-17T23:51:00':'2026-11-18T01:12:00'))return false;}}
 if(st.route?.length!==3||st.route.some((id,i)=>id!==CCTV_SECRET.route[i]))return false;
 if(st.routeTimes?.length!==3||st.routeTimes.some((str,i)=>String(str).trim()!==CCTV_SECRET.movementTimes[i]))return false;
 if(st.assessment!=='cechy_bez_twarzy'||st.blindspot!=='nisza_niewidoczna'||st.source!=='VIS-06')return false;
 // Czas i przemieszczanie: odstęp >= 80 s z rejonu audytu do drzwi; >= 135 s od drzwi do stanowisk.
 const corrected=st.route.map((id,i)=>{const f=CCTV_BYID[id];return cctvRawTime(f.rawISO)-CCTV_SECRET.offsets[f.camera]*1000;});
 if(corrected[1]-corrected[0]<80000||corrected[2]-corrected[1]<135000)return false;
 if(String(st.notes||'').startsWith('m5:'))return mini5Correct('cctv',st.notes);
 if(!String(st.notes||'').trim()||String(st.notes).trim().length<85)return false;
 return true;
}
function cctvFiltered(){const f=STATE.cctv.filters,q=norm(f.query);return CCTV_RECORDS.filter(x=>(!f.camera||x.camera===f.camera)&&(!f.type||x.type===f.type)&&(!f.date||x.display.startsWith(f.date))&&(!q||norm(x.id+' '+x.detail+' '+x.scene+' '+x.display+' '+x.marker+' '+x.serial).includes(q)));}
function cctvFrameSvg(f){const cam=f?.camera||'A',seed=f?Number(f.id.replace(/\D/g,'')):0;const figure=f&&['RUCH','RUCH TECH.'].includes(f.type);const light=f&&f.type==='ŚWIATŁO';const x=115+(seed*17)%135;const bright=light?'#d1c28b':'#45515a';const door=cam==='B';
 return `<svg viewBox="0 0 400 225" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Uproszczona wizualizacja kadru zarejestrowanego przez kamerę ${cam}"><defs><pattern id="scan${seed}" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 3h4" stroke="#d7e4eb" stroke-opacity=".05"/></pattern></defs><rect width="400" height="225" fill="#151d20"/><path d="M0 35h400M0 132h400M0 210h400" stroke="#39464b" stroke-width="2"/><path d="M0 210L150 128L250 128L400 210M145 0L145 128M252 0L252 128" fill="none" stroke="#566168" stroke-width="2"/>${door?'<rect x="195" y="55" width="70" height="95" fill="#242e33" stroke="#667d8c"/><rect x="261" y="100" width="13" height="22" fill="#526b62"/>':''}<path d="M20 24H380" stroke="${bright}" stroke-width="6" opacity="${light?'.8':'.18'}"/>${figure?`<g transform="translate(${x},105)" fill="#182125" stroke="#8d9494" stroke-opacity=".7"><ellipse cx="0" cy="-16" rx="12" ry="15"/><path d="M-12 0L14 0L20 51L-21 51Z"/><path d="M-14 49L-15 82M13 49L12 82" stroke="#8d9494" stroke-width="7"/><rect x="17" y="28" width="21" height="29" fill="#29353a"/></g>`:''}<rect width="400" height="225" fill="url(#scan${seed})"/><text x="10" y="16" fill="#c0caca" font-size="11" font-family="monospace">REC · CAM-${cam} · ${f?f.display:'BRAK SYGNAŁU'}</text><text x="12" y="205" fill="#aeb7ae" font-size="10" font-family="monospace">${f?f.scene:'NIE WYBRANO KADRU'}</text></svg>`;}
function cctvRender(){const root=$('cctvWorkspace');if(!root)return;const st=STATE.cctv;
 const pills=CCTV_INPUT.concat(['VIS-10']).map(x=>`<span class="cv-badge ${STATE.found.has(x)?'have':''}">${esc(docName(x))} · ${STATE.found.has(x)?'uzyskano':'do odnalezienia'}</span>`).join('');
 if(CCTV_INPUT.filter(x=>STATE.found.has(x)).length<2){
 root.innerHTML=`<div class="surface padded"><div class="eyebrow">ANALIZA MONITORINGU</div><h2 style="margin-top:10px">Synchronizator CCTV</h2><p>Archiwum jest zabezpieczone. Odszukaj w aktach co najmniej dwa niezależne materiały dotyczące zapisu kamer lub sygnalizacji, aby uruchomić podgląd. Pełna kalibracja wymaga kompletnego zestawu źródeł.</p><div class="cv-badges" style="margin-top:16px">${pills}</div></div>`;return;
 }
 root.innerHTML=`<div class="cv-shell"><div class="surface padded"><div class="cv-head"><div><div class="eyebrow">ANALIZA MONITORINGU</div><h2 style="margin-top:7px">Synchronizator CCTV</h2><p class="muted small">Trzy rejestratory, odmienne zegary, zakłócenia i martwe pola. Porównaj dwa zdarzenia niezależnej sygnalizacji, zanim wyciągniesz wniosek o ruchu.</p></div><span class="chip">${CCTV_RECORDS.length} kadrów</span></div><div class="cv-badges" style="margin-top:14px">${pills}</div></div>
 <div class="surface padded"><div class="eyebrow">ARCHIWUM ZAREJESTROWANYCH KLATEK</div><div class="cv-filter" style="margin-top:13px"><label>Kamera<select id="cvCamera"><option value="">Wszystkie</option>${['A','B','C'].map(x=>`<option ${st.filters.camera===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Charakter zapisu<select id="cvType"><option value="">Wszystkie</option>${['ŚWIATŁO','RUCH','RUCH TECH.','BEZ RUCHU','USTERKA'].map(x=>`<option ${st.filters.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Dzień rejestratora<select id="cvDate"><option value="">Oba dni</option><option value="17.11" ${st.filters.date==='17.11'?'selected':''}>17 listopada</option><option value="18.11" ${st.filters.date==='18.11'?'selected':''}>18 listopada</option></select></label><label class="cv-wide">Wyszukiwanie opisu lub oznaczeń<input id="cvQuery" placeholder="Kadr, seria, szczegół obrazu..." value="${esc(st.filters.query)}"></label></div><div class="cv-grid" style="margin-top:15px"><div><div class="cv-tablebox"><table class="cv-table"><thead><tr><th>Rekord</th><th>Kamera / nakładka</th><th>Typ</th><th>Opis zapisu</th><th>Źródło</th></tr></thead><tbody id="cvRows"></tbody></table></div><div class="cv-foot"><span class="muted small" id="cvCount"></span><div class="formline"><button class="btn subtle" id="cvPrev">Poprzednie</button><button class="btn subtle" id="cvNext">Następne</button></div></div></div><div class="cv-inspector"><div class="eyebrow">PODGLĄD WYBRANEJ KLATKI</div><div class="cv-shot" id="cvShot">${cctvFrameSvg(CCTV_BYID[st.selected])}</div><div id="cvMeta" class="cv-meta"></div><div class="cv-slot"><label class="muted small">Przypisz wybrany kadr do pola raportu<select id="cvSlot"><option value="A1">Kotwica 1 kamery A</option><option value="A2">Kotwica 2 kamery A</option><option value="B1">Kotwica 1 kamery B</option><option value="B2">Kotwica 2 kamery B</option><option value="C1">Kotwica 1 kamery C</option><option value="C2">Kotwica 2 kamery C</option><option value="R1">Trasa: punkt 1 (A)</option><option value="R2">Trasa: punkt 2 (B)</option><option value="R3">Trasa: punkt 3 (C)</option></select></label><button class="btn subtle" id="cvAssign">Przypnij do raportu</button></div></div></div></div>
 <div class="surface padded cv-report"><div class="eyebrow">KALIBRACJA REJESTRATORÓW</div><h3 style="margin:9px 0">Niezależne kotwice i korekta zegarów</h3><p class="cv-help">Znak „+” oznacza, że zegar kamery wyprzedza czas centralny. Podaj przesunięcia w całkowitych sekundach; każda korekta musi zgadzać się z obydwoma sygnałami.</p><div class="cv-offsets">${['A','B','C'].map(cam=>`<label>Kamera ${cam} — odchylenie [s]<input data-cv-offset="${cam}" type="number" step="1" placeholder="± sekundy" value="${esc(st.offsets[cam])}"></label>`).join('')}</div><div class="cv-picks" style="margin-top:14px">${['A','B','C'].map(cam=>`<section><b>Kamera ${cam}</b><div class="cv-pick">Sygnał 1 <b id="cvAssigned${cam}1">${esc(st.anchor[cam+'1']||'—')}</b><button data-cv-clear="${cam}1">Usuń</button></div><div class="cv-pick">Sygnał 2 <b id="cvAssigned${cam}2">${esc(st.anchor[cam+'2']||'—')}</b><button data-cv-clear="${cam}2">Usuń</button></div></section>`).join('')}</div></div>
 <div class="surface padded cv-report"><div class="eyebrow">REKONSTRUKCJA PRZEJŚCIA</div><h3 style="margin:9px 0">Zestawienie niezależnych klatek ruchu</h3><p class="cv-help">Wybrane punkty muszą tworzyć kolejny, fizycznie możliwy odcinek drogi. Godzinę centralną podaj ręcznie po odjęciu korekty zegara kamery.</p><div class="cv-route">${['A','B','C'].map((cam,i)=>`<div class="cv-route-card"><b>Punkt ${i+1} / kamera ${cam}</b><p class="cv-id" id="cvRouteId${i}">${esc(st.route[i]||'—')}</p><label>Czas centralny (HH:MM:SS)<input data-cv-route-time="${i}" placeholder="HH:MM:SS" value="${esc(st.routeTimes[i])}"></label><button class="btn subtle" data-cv-remove-route="${i}" style="margin-top:8px">Usuń klatkę</button></div>`).join('')}</div><div class="cv-filter" style="margin-top:14px"><label class="cv-wide">Co naprawdę potwierdzają cechy osoby?<select id="cvAssess"><option value="">Wybierz zakres wniosku...</option><option value="identyfikacja">Widać twarz, tożsamość jest pewna</option><option value="cechy_bez_twarzy">Cechy i kierunek ruchu, bez pewnej identyfikacji</option><option value="atak">Obraz rejestruje moment przemocy</option></select></label><label class="cv-wide">Co z niszą przy stanowisku 3?<select id="cvBlind"><option value="">Wybierz...</option><option value="nisza_niewidoczna">Nisza jest poza polami tych trzech kamer</option><option value="nisza_pelna">Nisza jest stale widoczna z trzech kamer</option><option value="niewidoczni_nieobecni">Brak obrazu oznacza nieobecność ludzi</option></select></label><label class="cv-wide">Dokument niezależnego czasu<select id="cvSource"><option value="">Wybierz zdobyte źródło...</option>${DOCS.filter(x=>STATE.found.has(x.id)).map(x=>`<option value="${esc(x.id)}">${esc(x.id)} — ${esc(x.title)}</option>`).join('')}</select></label><div class="cv-wide">${mini5Select('cctv','cvNotes',st.notes||'')}</div></div><div class="formline" style="margin-top:13px"><button class="btn" id="cvSubmit" ${st.solved?'disabled':''}>Zatwierdź rekonstrukcję</button><span class="muted small" id="cvAttempts">Próby weryfikacji: ${st.attempts}</span></div><div class="cv-report-note" id="cvFeedback">${st.solved?'Raport został zweryfikowany. Trzy materiały dołączono do akt. Nie ustalono tożsamości osoby z twarzy.':'Wybierz kadry, wyznacz przesunięcia, złóż trasę i obroń zakres wniosku. Błędna hipoteza nie niszczy danych.'}</div></div></div>`;
 for(const [field,id] of [['camera','cvCamera'],['type','cvType'],['date','cvDate'],['query','cvQuery']])$(id).addEventListener('input',()=>{st.filters[field]=$(id).value;st.page=0;cctvRenderRows();});
 for(const cam of ['A','B','C'])root.querySelector(`[data-cv-offset="${cam}"]`).addEventListener('input',e=>st.offsets[cam]=e.target.value);
 root.querySelectorAll('[data-cv-route-time]').forEach(x=>x.addEventListener('input',e=>st.routeTimes[+e.target.dataset.cvRouteTime]=e.target.value));
 root.querySelectorAll('[data-cv-remove-route]').forEach(x=>x.addEventListener('click',()=>{st.route[+x.dataset.cvRemoveRoute]='';cctvRender();}));
 root.querySelectorAll('[data-cv-clear]').forEach(x=>x.addEventListener('click',()=>{st.anchor[x.dataset.cvClear]='';cctvRender();}));
 for(const [key,id] of [['assessment','cvAssess'],['blindspot','cvBlind'],['source','cvSource'],['notes','cvNotes']]){$(id).value=st[key];$(id).addEventListener('input',()=>st[key]=$(id).value.slice(0,2500));}
 $('cvSlot').value=st.slot;$('cvSlot').addEventListener('change',()=>st.slot=$('cvSlot').value);
 $('cvAssign').addEventListener('click',cctvAssign);$('cvSubmit').addEventListener('click',cctvSubmit);
 $('cvPrev').addEventListener('click',()=>{st.page=Math.max(0,st.page-1);cctvRenderRows();});$('cvNext').addEventListener('click',()=>{st.page++;cctvRenderRows();});
 cctvRenderRows();cctvRenderInspector();}
function cctvRenderRows(){const st=STATE.cctv,list=cctvFiltered(),pages=Math.max(1,Math.ceil(list.length/40));st.page=Math.min(st.page,pages-1);const now=list.slice(st.page*40,(st.page+1)*40);
 $('cvCount').textContent=`${list.length} z ${CCTV_RECORDS.length} kadrów · strona ${st.page+1}/${pages}`;
 $('cvPrev').disabled=st.page===0;$('cvNext').disabled=st.page>=pages-1;
 $('cvRows').innerHTML=now.map(x=>`<tr data-cv-id="${esc(x.id)}" class="${st.selected===x.id?'cv-active':''}"><td><b>${esc(x.id)}</b></td><td>Kamera ${esc(x.camera)}<small>${esc(x.display)}</small></td><td>${esc(x.type)}</td><td>${esc(x.detail)}</td><td>${esc(x.origin)}<small>${esc(x.quality)}</small></td></tr>`).join('');
 $('cvRows').querySelectorAll('[data-cv-id]').forEach(row=>row.addEventListener('click',()=>{st.selected=row.dataset.cvId;cctvRenderRows();cctvRenderInspector();}));}
function cctvRenderInspector(){const f=CCTV_BYID[STATE.cctv.selected];$('cvShot').innerHTML=cctvFrameSvg(f);$('cvMeta').innerHTML=f?`<b>${esc(f.id)}</b> · kamera ${esc(f.camera)} · nakładka ${esc(f.display)}<div>Obszar: ${esc(f.scene)}</div><div>Analiza obrazu: ${esc(f.detail)}</div><div>Archiwum: ${esc(f.origin)} · ocena ${esc(f.quality)}</div>`:'Wybierz kadr z archiwum, aby zobaczyć szczegóły.';}
function cctvAssign(){const st=STATE.cctv,f=CCTV_BYID[st.selected],key=st.slot;if(!f){toast('Najpierw wybierz kadr.');return;}
 const requiredCam=key.startsWith('R')?['A','B','C'][Number(key[1])-1]:key[0];if(f.camera!==requiredCam){toast('Kadr musi pochodzić z właściwej kamery.');return;}
 if(key.startsWith('R'))st.route[Number(key[1])-1]=f.id;else st.anchor[key]=f.id;
 cctvRender();toast('Przypisano kadr do roboczego raportu.');}
function cctvSubmit(){const st=STATE.cctv;st.attempts++;if(cctvCheck(st,STATE.found)){st.solved=true;for(const id of CCTV_OUT)STATE.found.add(id);PS_EVENTS.laboratory('cctv',CCTV_OUT);renderDocs();renderAttached();toast('Zweryfikowano analizę CCTV. Trzy materiały dołączono do akt.');cctvRefresh();return;}
 const bad=[];if(!cctvHasInputs())bad.push('Brak pełnego kompletu czterech dokumentów źródłowych.');if(!STATE.found.has('VIS-10'))bad.push('Brakuje planu martwych pól.');
 if(Object.values(st.anchor).filter(Boolean).length<6)bad.push('Nie przypisano obu sygnałów wszystkim trzem kamerom.');
 if(Object.values(st.offsets).filter(x=>x!=='').length<3)bad.push('Nie wprowadzono wszystkich korekt zegarów.');
 if(st.route.filter(Boolean).length<3||st.routeTimes.filter(Boolean).length<3)bad.push('Nie odtworzono trzech punktów drogi wraz z czasami centralnymi.');
 if(!st.notes||(st.notes.startsWith('m5:')?!mini5Correct('cctv',st.notes):st.notes.trim().length<85))bad.push('Wybierz wniosek uwzględniający zarówno chronologię, jak i ograniczenia nagrania.');
 if(!bad.length)bad.push('Nie udało się potwierdzić zgodności czasów, wzajemnego dopasowania sygnałów i wybranej trasy. Sprawdź kadr oraz kierunek korekty, a także zakres wniosku.');
 $('cvFeedback').textContent=bad.join('\n');$('cvAttempts').textContent='Próby weryfikacji: '+st.attempts;}
function cctvRestore(saved){const st=CCTV_DEFAULT();if(saved&&typeof saved==='object'){
 if(saved.filters&&typeof saved.filters==='object')for(const k of Object.keys(st.filters))if(typeof saved.filters[k]==='string')st.filters[k]=saved.filters[k].slice(0,90);
 if(typeof saved.page==='number'&&saved.page>=0&&saved.page<100)st.page=Math.floor(saved.page);
 if(typeof saved.selected==='string'&&CCTV_BYID[saved.selected])st.selected=saved.selected;
 if(typeof saved.slot==='string'&&/^(?:[ABC][12]|R[123])$/.test(saved.slot))st.slot=saved.slot;
 if(saved.offsets&&typeof saved.offsets==='object')for(const cam of ['A','B','C'])if(['string','number'].includes(typeof saved.offsets[cam]))st.offsets[cam]=String(saved.offsets[cam]).slice(0,10);
 if(saved.anchor&&typeof saved.anchor==='object')for(const key of Object.keys(st.anchor))if(CCTV_BYID[saved.anchor[key]])st.anchor[key]=saved.anchor[key];
 if(Array.isArray(saved.route))st.route=st.route.map((x,i)=>CCTV_BYID[saved.route[i]]?saved.route[i]:'');
 if(Array.isArray(saved.routeTimes))st.routeTimes=st.routeTimes.map((x,i)=>typeof saved.routeTimes[i]==='string'?saved.routeTimes[i].slice(0,20):'');
 for(const k of ['assessment','blindspot','source','notes'])if(typeof saved[k]==='string')st[k]=saved[k].slice(0,2500);
 st.attempts=Number.isInteger(saved.attempts)?Math.min(10000,Math.max(0,saved.attempts)):0;
 st.solved=cctvCheck(st,STATE.found);if(st.solved)for(const id of CCTV_OUT)STATE.found.add(id);
 }STATE.cctv=st;}
function cctvReset(){STATE.cctv=CCTV_DEFAULT();for(const id of CCTV_OUT)STATE.found.delete(id);if($('cctvWorkspace')&&!$('cctvPanel').hidden)cctvRender();}
function cctvRefresh(){tcmsCards();if($('cctvPanel')&&!$('cctvPanel').hidden)cctvRender();}


